from pydantic_ai import FunctionToolset
from pydantic_ai.tools import Tool

def _run_shell_safe(command: str, cwd: str = '.', timeout: float = 120.0) -> str:
    """Shell tool with non-interactive env + timeout — prevents LLM from hanging harness."""
    env = {**os.environ, 'GIT_TERMINAL_PROMPT': '0', 'PYTHONUNBUFFERED': '1'}
    try:
        result = subprocess.run(command, shell=True, cwd=cwd, timeout=timeout, env=env, capture_output=True, text=True)
        return result.stdout + result.stderr
    except subprocess.TimeoutExpired:
        raise ToolError(json.dumps({'error': 'command timed out', 'timeout': timeout}))
    except Exception as exc:
        raise ToolError(json.dumps({'error': str(exc), 'error_type': type(exc).__name__}))

# Risk-classified tool registration with strict schema
shell_tool = Tool(_run_shell_safe, strict=True, timeout=30)
registry = FunctionToolset([shell_tool])  # strict=True → rejects schema-invalid calls
# Unknown tools → ToolError (visible in conversation, triggers self-correction)
